      "path": "lib/index.js",
      "content": "/**
 * dsh-ultramath — UltraMath 数学建模竞赛多 Agent 求解插件（bundle）。
 *
 * 纯 node 半侧：主机启动时把打包的 presets/ 树幂等同步到 DSH 的 agent-presets
 * 发现根（~/.dsh/.agent-presets），使「UltraMath」主控 + 4 个角色预设可被新会话选择，
 * 并通过 systemPrompt 区块公告插件能力。无浏览器半侧、无路由、无 agent 工具——
 * 工具由预设自身提供。
 *
 * skills 不依赖 dsh-skill-filesystem 自动扫描 npm 包：apply() 时通过
 * syncSkillTrees() 把根 SKILL.md 与 skills/模型库/ 幂等同步到 DSH 技能发现根
 * ~/.dsh/skills/ultramath/，使「ultramath」主入口技能与模型库文档可被发现。
 */
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmdirSync, statSync, unlinkSync, utimesSync, writeFileSync } from "node:fs";
import { basename, dirname, isAbsolute, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { homedir, tmpdir } from "node:os";
import z from "schemastery";

// ── DSH home 解析（DSH_HOME 环境变量优先，平台 home 兜底）───────────────────

/** 展开路径开头的 ~ 或 ~/（平台风格）。 */
function expandHome(path, home = homedir()) {
  if (path === "~") return home;
  if (path.startsWith("~/") || path.startsWith("~\\")) return join(home, path.slice(2));
  return path;
}

/** 解析 DSH 主目录。@param env 读 DSH_HOME 的环境；@param home 平台 home 兜底。 */
function resolveDshHome(env = process.env, home = homedir()) {
  const raw = env.DSH_HOME;
  if (raw !== undefined && raw.trim() !== "") {
    const expanded = expandHome(raw.trim(), home);
    return isAbsolute(expanded) ? expanded : join(process.cwd(), expanded);
  }
  return join(home, ".dsh");
}

/** 从实时环境解析 DSH 主目录。 */
function dshHome() {
  return resolveDshHome();
}

// ── agent.cordis.yml 结构校验（无依赖，只解析扁平 row 元数据）────────────────

/** 顶层 row 开行：- id: <id>。 */
const ROW_RE = /^-\s+id:\s*(.*)$/;
/** 任意顶层列表项（用于缺少 id 的诊断）。 */
const ITEM_RE = /^-\s/;
/** 两空格缩进的扁平元数据键：  name: <value>。 */
const META_RE = /^ {2}([A-Za-z][A-Za-z0-9_-]*):\s*(.*)$/;
/** dsh agent-presets loader 允许挂载的 name 前缀形式。 */
const NAME_PREFIX_RE = /^(\.\/|@|cordis:)/;

/** 去掉标量外的一对单引号或双引号。 */
function unquote(value) {
  if (value.length >= 2) {
    const first = value[0];
    if ((first === "'" || first === '"') && value.endsWith(first)) return value.slice(1, -1);
  }
  return value;
}

/**
 * 校验 agent.cordis.yml 的结构契约：每个顶层 row 以 - id: <id> 开头，
 * name/group 键两空格缩进；嵌套 config/isolate 体不透明。返回问题列表，空数组=合法。
 */
function validateAgentCordis(text) {
  const errors = [];
  const normalized = text.replace(/\r\n/g, "\n");
  if (normalized.trim() === "") return ["document is empty"];
  const seenIds = new Set();
  const current = { id: null, name: null, group: null };
  const closeRow = () => {
    if (current.id === null) return;
    if (current.name === null) {
      errors.push('row "' + current.id + '": missing "name" key');
    } else if (!NAME_PREFIX_RE.test(current.name)) {
      errors.push('row "' + current.id + '": name "' + current.name + '" must start with "./", "@" or "cordis:"');
    }
    if (current.group === "true" && current.name !== "cordis:group") {
      errors.push('row "' + current.id + '": "group: true" requires name "cordis:group"');
    }
    current.name = null;
    current.group = null;
    current.id = null;
  };
  const lines = normalized.split("\n");
  for (let index = 0; index < lines.length; index += 1) {
    const lineNo = index + 1;
    const line = lines[index];
    const trimmed = line.trim();
    if (trimmed === "" || trimmed.startsWith("#")) continue;
    const row = ROW_RE.exec(line);
    if (row !== null) {
      closeRow();
      const id = row[1].trim();
      if (id === "") {
        errors.push('line ' + lineNo + ': empty row id');
        current.id = null;
      } else {
        if (seenIds.has(id)) errors.push('line ' + lineNo + ': duplicate row id "' + id + '"');
        seenIds.add(id);
        current.id = id;
      }
      current.name = null;
      current.group = null;
      continue;
    }
    if (current.id === null) {
      if (ITEM_RE.test(line)) {
        errors.push('line ' + lineNo + ': list item does not declare an "id:"');
      } else if (/^\S/.test(line)) {
        errors.push('line ' + lineNo + ': content outside a "- id:" row');
      }
      continue;
    }
    const meta = META_RE.exec(line);
    if (meta !== null) {
      const value = unquote(meta[2].trim());
      if (meta[1] === "name") current.name = value;
      else if (meta[1] === "group") current.group = value;
      continue;
    }
    if (/^ {2}/.test(line)) continue; // 两空格以上缩进 = 嵌套体，此处不透明
    errors.push('line ' + lineNo + ': unexpected content in row "' + current.id + '"');
  }
  closeRow();
  return errors;
}

// ── SKILL.md 结构校验（DSH skill-filesystem 需要 frontmatter + 主入口章节）──

/**
 * 校验插件主入口 SKILL.md 的结构契约。返回问题列表，空数组=合法。
 * DSH 的 dsh-skill-filesystem 要求 YAML frontmatter 含 name/description；
 * 主入口还需要保留根目录契约、角色分工和模型库索引章节。
 */
export function validateSkillMarkdown(text) {
  const errors = [];
  const normalized = text.replace(/\r\n/g, "\n");
  if (!/^---\n/.test(normalized)) {
    errors.push("SKILL.md missing YAML frontmatter (must start with '---')");
  } else {
    const end = normalized.indexOf("\n---", 3);
    const frontmatter = end === -1 ? normalized : normalized.slice(0, end);
    if (!/\bname:\s*ultramath\b/.test(frontmatter)) {
      errors.push('SKILL.md frontmatter missing "name: ultramath"');
    }
    if (!/\bdescription:\s*\S/.test(frontmatter)) {
      errors.push("SKILL.md frontmatter missing description");
    }
  }
  if (!normalized.includes("## 0.")) {
    errors.push('SKILL.md missing section "## 0." (entry/root contract)');
  }
  if (!normalized.includes("5 角色分工")) {
    errors.push('SKILL.md missing section "5 角色分工"');
  }
  if (!normalized.includes("模型库索引") && !normalized.includes("## 3.")) {
    errors.push('SKILL.md missing 模型库索引 section');
  }
  if (!normalized.includes("SKILL_ROOT")) {
    errors.push("SKILL.md missing SKILL_ROOT contract");
  }
  return errors;
}

// ── 幂等同步（字节相同跳过；结构校验失败进入 failed）────────────────────────

const MTIME_TOLERANCE_MS = 1000;

/** 递归收集 root 下所有文件绝对路径。 */
function filesUnder(root) {
  const out = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir)) {
      const path = join(dir, entry);
      if (statSync(path).isDirectory()) walk(path);
      else out.push(path);
    }
  };
  walk(root);
  return out;
}

/** 文件身份是字节：mtime 快速负向检查，落到规范化（LF 行尾）字节比较。 */
function sameFile(a, b) {
  const sourceStat = statSync(a);
  const targetStat = statSync(b);
  if (Math.abs(sourceStat.mtimeMs - targetStat.mtimeMs) > MTIME_TOLERANCE_MS) return false;
  return normalizedBytes(a).equals(normalizedBytes(b));
}

/** 规范化文本行尾（CRLF/CR → LF），保证 YAML/MD 等在 DSH 端解析稳定。 */
function normalizeEol(text) {
  return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

/** 读取文件并返回规范化（LF 行尾）后的 UTF-8 字节。 */
function normalizedBytes(file) {
  return Buffer.from(normalizeEol(readFileSync(file, "utf8")), "utf8");
}

// ── Windows 安全文件操作 ──────────────────────────────────────────────
// 兼容性修复（GitHub Issue #1）：部分 Windows 环境（Node/安全软件组合）下，
// cpSync 递归复制「源目录名含中文」会硬崩溃整个进程（0xC0000409），
// rmSync 对非 ASCII 路径静默失效。这里用逐文件拷贝/删除替代 cpSync(recursive)
// 与 rmSync(recursive)，行为与语义完全一致（含 preserveTimestamps 语义，
// 保住幂等判断），且对任意路径安全。

/** 删除单个文件（force 语义：不存在视为成功）。 */
function unlinkFile(path) {
  try {
    unlinkSync(path);
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
  }
}

/** 递归删除目录树（force 语义：不存在视为成功）。 */
function removeTree(path) {
  let stat;
  try {
    stat = statSync(path);
  } catch {
    return;
  }
  if (stat.isDirectory()) {
    for (const entry of readdirSync(path)) {
      removeTree(join(path, entry));
    }
    rmdirSync(path);
  } else {
    unlinkSync(path);
  }
}

/** 复制单个文件并保留 mtime（语义同 cpSync 单文件 + preserveTimestamps）。 */
function copyFilePreserving(src, dest) {
  writeFileSync(dest, normalizedBytes(src));
  const stat = statSync(src);
  utimesSync(dest, stat.atime, stat.mtime);
}

/** 递归复制目录树（逐文件拷贝 + 保留 mtime，替代 cpSync(recursive)）。 */
function copyTree(sourceDir, targetDir) {
  mkdirSync(targetDir, { recursive: true });
  for (const entry of readdirSync(sourceDir)) {
    const src = join(sourceDir, entry);
    const dest = join(targetDir, entry);
    if (statSync(src).isDirectory()) {
      copyTree(src, dest);
    } else {
      copyFilePreserving(src, dest);
    }
  }
}

/** 删除不在 keep（相对路径）内的文件，再删除因此留空的目录（严格限于 root 内）。 */
function pruneExtras(root, keep) {
  const parents = new Set();
  for (const file of filesUnder(root)) {
    if (!keep.has(relative(root, file))) {
      parents.add(dirname(file));
      unlinkFile(file);
    }
  }
  for (const start of parents) {
    let dir = start;
    while (dir !== undefined && relative(root, dir) !== "") {
      if (existsSync(dir) && readdirSync(dir).length === 0) {
        rmdirSync(dir);
        dir = dirname(dir);
      } else {
        dir = undefined;
      }
    }
  }
}

/** 校验磁盘上已同步预设的 agent.cordis.yml。 */
function validatePresetAgentFile(presetDir) {
  const agent = join(presetDir, "agent.cordis.yml");
  if (!existsSync(agent)) return ["agent.cordis.yml is missing from the preset tree"];
  return validateAgentCordis(readFileSync(agent, "utf8"));
}

/** 把 sourceDir 幂等拷贝到 targetDir。 */
function syncOnePreset(sourceDir, targetDir) {
  const sourceFiles = filesUnder(sourceDir);
  const sourceSet = new Set(sourceFiles.map((file) => relative(sourceDir, file)));
  if (existsSync(targetDir) && !statSync(targetDir).isDirectory()) {
    removeTree(targetDir);
  }
  if (!existsSync(targetDir)) {
    copyTree(sourceDir, targetDir);
    pruneExtras(targetDir, sourceSet);
    return "synced";
  }
  let dirty = false;
  for (const file of sourceFiles) {
    const dest = join(targetDir, relative(sourceDir, file));
    if (!existsSync(dest) || !sameFile(file, dest)) {
      dirty = true;
      break;
    }
  }
  if (!dirty) {
    for (const file of filesUnder(targetDir)) {
      if (!sourceSet.has(relative(targetDir, file))) {
        dirty = true;
        break;
      }
    }
  }
  if (!dirty) return "current";
  pruneExtras(targetDir, sourceSet);
  copyTree(sourceDir, targetDir);
  pruneExtras(targetDir, sourceSet);
  return "synced";
}

/**
 * 把 sourceRoot 下每个预设目录同步到 targetRoot，再删除 retire 中列出但已不再
 * 随包分发的目标目录。每个同步（或已是最新）的预设做结构校验，失败进入 failed。
 */
function syncPresetTrees(sourceRoot, targetRoot, retire = []) {
  const result = { synced: [], current: [], failed: [], retired: [] };
  mkdirSync(targetRoot, { recursive: true });
  if (existsSync(sourceRoot)) {
    for (const entry of readdirSync(sourceRoot)) {
      const source = join(sourceRoot, entry);
      if (!statSync(source).isDirectory()) continue;
      const id = basename(source);
      const targetDir = join(targetRoot, id);
      let outcome;
      try {
        outcome = syncOnePreset(source, targetDir);
      } catch (error) {
        result.failed.push({ id, error: error instanceof Error ? error.message : String(error) });
        continue;
      }
      try {
        const problems = validatePresetAgentFile(targetDir);
        if (problems.length > 0) {
          result.failed.push({ id, error: 'agent.cordis.yml failed validation: ' + problems.join('; ') });
        } else if (outcome === "synced") {
          result.synced.push(id);
        } else {
          result.current.push(id);
        }
      } catch (error) {
        result.failed.push({ id, error: error instanceof Error ? error.message : String(error) });
      }
    }
  }
  for (const id of retire) {
    if (existsSync(join(sourceRoot, id))) continue;
    const stale = join(targetRoot, id);
    if (existsSync(stale) && statSync(stale).isDirectory()) {
      removeTree(stale);
      result.retired.push(id);
    }
  }
  return result;
}

// ── 技能幂等同步（把根 SKILL.md + skills/模型库 同步为 ~/.dsh/skills/ultramath）──

/**
 * 同步插件技能树：把 sourceRoot（插件包根）下的 SKILL.md、skills/模型库/、
 * templates/（若存在）与 scripts/（审稿脚本，若存在）组装成 targetRoot/ultramath/
 * 技能目录。复用 syncOnePreset 的字节比较与 prune 逻辑；同步后校验 SKILL.md，
 * 非法则进入 failed；源含 templates/ 时同时校验 templates/论文/论文.tex 已同步；
 * 源含 scripts/ 时校验 scripts/check_figures.py 已同步。
 */
export function syncSkillTrees(sourceRoot, targetRoot, retire = []) {
  const result = { synced: [], current: [], failed: [], retired: [] };
  const skillId = "ultramath";
  mkdirSync(targetRoot, { recursive: true });
  const targetDir = join(targetRoot, skillId);
  const sourceSkill = join(sourceRoot, "SKILL.md");
  const sourceLibrary = join(sourceRoot, "skills", "模型库");
  if (!existsSync(sourceSkill)) {
    result.failed.push({ id: skillId, error: "SKILL.md is missing from the plugin root" });
  } else {
    const staging = mkdtempSync(join(tmpdir(), "dsh-ultramath-skill-"));
    try {
      const stagedSkill = join(staging, "ultramath");
      mkdirSync(stagedSkill, { recursive: true });
      copyFilePreserving(sourceSkill, join(stagedSkill, "SKILL.md"));
      if (existsSync(sourceLibrary)) {
        copyTree(sourceLibrary, join(stagedSkill, "模型库"));
      }
      // 随包 templates/（论文模板，无 fonts）与 SKILL.md + 模型库 一起同步，
      // 使 persona 的 SKILL_ROOT/templates/论文/ 引用运行时可解析。
      const sourceTemplates = join(sourceRoot, "templates");
      const hasTemplates = existsSync(sourceTemplates);
      if (hasTemplates) {
        copyTree(sourceTemplates, join(stagedSkill, "templates"));
      }
      // v0.6.1: 审稿脚本（check_*.py + review_loop/）随技能树同步，使审稿人
      // persona 的 SKILL_ROOT/scripts/ 引用运行时可解析；仅拷贝随包脚本，
      // 开发期脚本（test-lib/validate/sync-standalone 等）不入技能树。
      const sourceScripts = join(sourceRoot, "scripts");
      const hasScripts = existsSync(sourceScripts);
      if (hasScripts) {
        const stagedScripts = join(stagedSkill, "scripts");
        mkdirSync(stagedScripts, { recursive: true });
        for (const entry of readdirSync(sourceScripts)) {
          if (entry === "review_loop" && statSync(join(sourceScripts, entry)).isDirectory()) {
            copyTree(join(sourceScripts, entry), join(stagedScripts, entry));
          } else if (/^check_.+\.py$/.test(entry) && statSync(join(sourceScripts, entry)).isFile()) {
            copyFilePreserving(join(sourceScripts, entry), join(stagedScripts, entry));
          }
        }
      }
      let outcome;
      try {
        outcome = syncOnePreset(stagedSkill, targetDir);
      } catch (error) {
        result.failed.push({ id: skillId, error: error instanceof Error ? error.message : String(error) });
        return result;
      }
      const problems = validateSkillMarkdown(readFileSync(join(targetDir, "SKILL.md"), "utf8"));
      // 源含 templates/ 时,校验核心模板文件已随技能树同步到位(否则 persona 运行时不可用)。
      let templatesProblem = "";
      if (hasTemplates && !existsSync(join(targetDir, "templates", "论文", "论文.tex"))) {
        templatesProblem = "templates/论文/论文.tex is missing from the synced skill tree";
      }
      // 源含 scripts/ 时,校验核心审稿脚本已同步到位。
      let scriptsProblem = "";
      if (hasScripts && !existsSync(join(targetDir, "scripts", "check_figures.py"))) {
        scriptsProblem = "scripts/check_figures.py is missing from the synced skill tree";
      }
      if (problems.length > 0) {
        result.failed.push({ id: skillId, error: "SKILL.md failed validation: " + problems.join("; ") });
      } else if (templatesProblem) {
        result.failed.push({ id: skillId, error: templatesProblem });
      } else if (scriptsProblem) {
        result.failed.push({ id: skillId, error: scriptsProblem });
      } else if (outcome === "synced") {
        result.synced.push(skillId);
      } else {
        result.current.push(skillId);
      }
    } finally {
      removeTree(staging);
    }
  }
  for (const id of retire) {
    if (id === skillId) continue;
    const stale = join(targetRoot, id);
    if (existsSync(stale) && statSync(stale).isDirectory()) {
      removeTree(stale);
      result.retired.push(id);
    }
  }
  return result;
}

