});

/** schema 默认值，供手工构造的测试上下文重读。 */
const DEFAULT_ANNOUNCE = true;

/** 公告区块在工具指导带内的顺序。 */
const SECTION_ORDER = 150;

// ── 退役资产清单（retire 接线，v0.6.1）───────────────────────────────
// 若未来某预设/技能目录从随包清单中改名或移除，把旧目录名填入对应数组，
// apply() 同步时会清理目标侧残留，避免改名后的旧目录永久滞留。
// 当前无已退役资产，保持空数组（机制已接线）。
const RETIRED_PRESETS = [];
const RETIRED_SKILLS = [];

/** 面向模型的公告：插件存在性、原理与边界。 */
export function ultramathGuidance() {
  const skillRoot = join(dshHome(), "skills", "ultramath");
  return (
