import os, sys, re, json, warnings
from pathlib import Path
from datetime import datetime
warnings.filterwarnings('ignore')

# ═══════════════════════════════════════════════════════════════
# 配置
# ═══════════════════════════════════════════════════════════════

# 色盲不安全的配色对 (禁止同时出现的色相组合)
COLORBLIND_UNSAFE_PAIRS = [
    ('red', 'green'),
    ('#EE6677', '#228833'),  # Paul Tol Bright red + green
