# 推荐 colormap 列表
RECOMMENDED_CMAPS = {'cividis', 'viridis', 'plasma', 'inferno', 'magma',
                     'RdBu_r', 'RdBu', 'coolwarm', 'PiYG', 'PRGn'}

# 最小文件大小 (低于此值认为图表异常)
MIN_FILE_SIZE_KB = 5

# 合理尺寸范围 (像素)
MIN_WIDTH = 600
MIN_HEIGHT = 400


# ═══════════════════════════════════════════════════════════════
# 检查函数
