def check_dpi(filepath):
    """检查 DPI"""
    try:
        from PIL import Image
        img = Image.open(filepath)
        dpi = img.info.get('dpi', (72, 72))
        width, height = img.size
        return {
            'dpi_x': dpi[0],
            'dpi_y': dpi[1],
            'width': width,
            'height': height,
            'score': 2.0 if dpi[0] >= 150 else (1.0 if dpi[0] >= 96 else 0),
            'issues': [] if dpi[0] >= 150 else [f'DPI={dpi[0]:.0f} < 150']
        }
    except Exception as e:
        return {'dpi_x': 0, 'dpi_y': 0, 'width': 0, 'height': 0,
                'score': 0, 'issues': [f'无法读取: {e}']}


def check_file_size(filepath):
    """检查文件大小"""
    size_kb = os.path.getsize(filepath) / 1024
    issues = []
    score = 2.0
    if size_kb < MIN_FILE_SIZE_KB:
        issues.append(f'文件过小 ({size_kb:.1f}KB < {MIN_FILE_SIZE_KB}KB), 可能空白或损坏')
        score = 0
    elif size_kb < 10:
        issues.append(f'文件偏小 ({size_kb:.1f}KB), 信息量可能不足')
        score = 1.0
    return {'size_kb': round(size_kb, 1), 'score': score, 'issues': issues}


def check_dimensions(filepath):
    """检查尺寸"""
    try:
        from PIL import Image
        img = Image.open(filepath)
        w, h = img.size
        issues = []
        score = 1.0
        if w < MIN_WIDTH or h < MIN_HEIGHT:
            issues.append(f'尺寸过小 ({w}×{h})')
            score = 0
        return {'width': w, 'height': h, 'score': score, 'issues': issues}
    except Exception:
        return {'width': 0, 'height': 0, 'score': 0, 'issues': ['无法读取尺寸']}


def check_py_source(figure_name, solve_dir, rel_path=None):
    """检查对应 .py 源码中的图表质量信号

    按图文件名/相对路径匹配对应的 问题X_求解.py:
      问题1/图片/fig1_*.png → 问题1/问题1_求解.py
      q2_*.png / 图3-1_*.png → 问题2|3/问题N_求解.py
    找不到对应文件时回退到扫描全部 .py。
    """
    issues = []
    score = 1.0  # [WARN] V12.2: 基础分从 3.0→1.0, 好图加分而非坏图扣分
    details = {}

    # ── 1. 按文件匹配对应的 .py ──
    # 优先从相对路径推断问题号: 问题1/图片/fig1_*.png → 问题1
    qnum = None
    if rel_path:
        m = re.search(r'问题(\d+)', rel_path.replace('\\', '/'))
        if m:
            qnum = m.group(1)
    # 再从图名推断: fig1_*.png / q2_*.png / 图3-1_*.png / 问题4_*.png
    if qnum is None:
        m = re.match(r'(?:fig|q|图|问题)(\d+)', figure_name)
        if m:
            qnum = m.group(1)
    # 最后从 solve_dir 自身推断
    if qnum is None and solve_dir:
        m = re.search(r'问题(\d+)', solve_dir.replace('\\', '/'))
        if m:
            qnum = m.group(1)

    # 归集与该问题相关的源码: 支持 问题N/问题N_求解.py、问题N/*.py、
    # 以及 公共模块/、核心理论/ 下的图表生成脚本(2024A/2025A 布局)
    matched_sources: list[str] = []
    if qnum:
        qdir = os.path.join(solve_dir, f'问题{qnum}')
        exact = os.path.join(qdir, f'问题{qnum}_求解.py')
        if os.path.exists(exact):
            matched_sources.append(exact)
        elif os.path.isdir(qdir):
            matched_sources.extend(
                os.path.join(qdir, f) for f in sorted(os.listdir(qdir))
                if f.endswith('.py')
            )
        for sub in ('公共模块', '核心理论'):
            sdir = os.path.join(solve_dir, sub)
            if os.path.isdir(sdir):
                matched_sources.extend(
                    os.path.join(sdir, f) for f in sorted(os.listdir(sdir))
                    if f.endswith('.py')
                )

    # ── 2. 读取源码 ──
    all_code = ''
    if matched_sources:
        for path in matched_sources:
            try:
                with open(path, 'r', encoding='utf-8') as fh:
                    all_code += fh.read()
            except Exception:
                continue
    else:
        # 回退: 扫描所有 .py
        for root, _, files in os.walk(solve_dir):
            for f in files:
                if f.endswith('.py') and '求解' in f:
                    try:
                        with open(os.path.join(root, f), 'r', encoding='utf-8') as fh:
                            all_code += fh.read()
                    except Exception:
                        continue
        if not all_code:
            return {'score': 0, 'issues': ['未找到 Python 源码, 无法检查标注'],
                    'details': {}}

    # ── 3. 检查项 (加分制) ──
    details['matched_py'] = matched_sources[0] if matched_sources else None
    details['matched_sources'] = matched_sources

    # figure_style 模块不进随包（AGENTS.md 约定），仅作信息记录，不参与计分，
    # 避免对无法使用的模块做系统性误判（v0.6.1 修复）。
    details['uses_figure_style'] = 'figure_style' in all_code

    # +0.5: 使用了 save_figure/save_fig 规范保存（而非 plt.savefig 裸调用）
    if re.search(r'save_figure|save_fig', all_code):
        details['uses_save_figure'] = True
        score += 0.5
    else:
        details['uses_save_figure'] = False
        issues.append('未使用 save_figure() 规范保存图表')

    # +0.5: 有轴标签
    if re.search(r'set_[xy]label', all_code):
        details['has_axis_labels'] = True
        score += 0.5
    else:
        details['has_axis_labels'] = False
        issues.append('图可能缺少轴标签')

    # 热力图数值标注检查
    if 'imshow' in all_code or 'heatmap' in all_code:
        if re.search(r'(ax\.text|annotate|heatmap_with_values)', all_code):
            score += 0.5  # 热力图有标注
        else:
            issues.append('热力图缺少数值标注')
            score -= 0.5

    # 检查 colormap
    cmaps_found = re.findall(r"cmap\s*=\s*['\"]([^'\"]+)['\"]", all_code)
    details['cmaps_used'] = list(set(cmaps_found))
    bad_cmaps = [c for c in cmaps_found if c not in RECOMMENDED_CMAPS and c not in {'gray', 'Greys'}]
    if bad_cmaps:
        issues.append(f'非推荐 colormap: {bad_cmaps}')
        score -= 0.5

    # 检查红绿配色 (V6.2: 从 COLORS.WARM 使用陶土红+鼠尾草绿也算)
    red_patterns = r'#B85042|#EE6677|#CC3311|TERRACOTTA|terracotta|WARM\[0\]'
    green_patterns = r'#7E9B7E|#228833|#117733|SAGE|sage|WARM\[1\]'
    has_red = bool(re.search(red_patterns, all_code))
    has_green = bool(re.search(green_patterns, all_code))
    details['colorblind_safe'] = not (has_red and has_green)
    if has_red and has_green:
        issues.append('[WARN] 代码中同时使用红绿色, 可能色盲不友好')
        score -= 1.0

    # 上限 3.0
    score = max(0, min(3.0, score))

    return {'score': round(score, 1), 'issues': issues, 'details': details}


def check_background_color(filepath):
    """检查 PNG 背景色是否一致（纯白 #FFFFFF）

    检查文件最外围像素和整体背景是否接近纯白。
    暖白底色（如 #FFFCF8）会被标记为警告。

    Returns:
        dict: {'is_pure_white': bool, 'dominant_bg': str, 'score': float, 'issues': [str]}
    """
    try:
        from PIL import Image
        import numpy as np
        img = Image.open(filepath).convert('RGB')
        arr = np.array(img)
        h, w = arr.shape[:2]
        # 采样四个角 + 四边中点
        corners = [
            arr[0, 0], arr[0, w-1], arr[h-1, 0], arr[h-1, w-1],
            arr[0, w//2], arr[h-1, w//2], arr[h//2, 0], arr[h//2, w-1],
        ]
        avg_corner = np.mean(corners, axis=0)
        r, g, b = avg_corner
        issues = []
        score = 1.0

        # 检查是否接近纯白 (每个通道 >= 250)
        if r >= 250 and g >= 250 and b >= 250:
            if r == 255 and g == 255 and b == 255:
                return {'is_pure_white': True, 'dominant_bg': '#FFFFFF',
                        'score': 1.0, 'issues': []}
            else:
                hex_color = f'#{int(r):02X}{int(g):02X}{int(b):02X}'
                issues.append(f'背景色为 {hex_color}（非纯白 #FFFFFF）, 可能为暖白底色')
                score = 0.5
                return {'is_pure_white': False, 'dominant_bg': hex_color,
                        'score': score, 'issues': issues}
        else:
            hex_color = f'#{int(r):02X}{int(g):02X}{int(b):02X}'
            return {'is_pure_white': False, 'dominant_bg': hex_color,
                    'score': 0.5, 'issues': [f'背景色 {hex_color} 偏离白色较远']}
    except Exception as e:
        return {'is_pure_white': False, 'dominant_bg': 'unknown',
                'score': 0, 'issues': [f'背景色检查失败: {e}']}


def check_unicode_boxes(filepath):
    """检查 PNG 中是否有 Unicode 方块渲染缺陷

    Unicode 方块在图片中通常表现为纯黑 (0,0,0) 或纯白 (255,255,255)
    的小矩形区域。本函数通过分析像素极值分布来检测。

    Args:
        filepath: PNG 文件路径

    Returns:
        dict: {'has_boxes': bool, 'score': float, 'issues': [str]}
    """
    try:
        from PIL import Image
        import numpy as np
        img = Image.open(filepath).convert('RGB')
        arr = np.array(img)
        gray = np.mean(arr, axis=2)
        dark_mask = gray < 10
        white_mask = gray > 245
        box_ratio = (dark_mask.sum() + white_mask.sum()) / gray.size
        if box_ratio > 0.05:
            return {
                'has_boxes': True,
                'ratio': round(box_ratio * 100, 1),
                'score': 0,
                'issues': [f'疑似 Unicode 方块 (极端像素 {box_ratio*100:.1f}%)']
            }
        return {
            'has_boxes': False,
            'ratio': round(box_ratio * 100, 1),
            'score': 1.0,
            'issues': []
        }
    except ImportError:
        return {'has_boxes': False, 'ratio': 0, 'score': 1.0, 'issues': ['PIL/numpy 未安装, 跳过']}
    except Exception as e:
        return {'has_boxes': False, 'ratio': 0, 'score': 1.0, 'issues': [f'检测异常: {e}']}


def generate_report(png_files, solve_dir):
    """生成完整审查报告"""
    results = []
    total_score = 0

    for png_path in png_files:
        name = os.path.basename(png_path)
        rel_path = os.path.relpath(png_path, solve_dir)

        dpi_info = check_dpi(png_path)
        size_info = check_file_size(png_path)
        dim_info = check_dimensions(png_path)
        bg_info = check_background_color(png_path)
        py_info = check_py_source(name, solve_dir, rel_path)
        unicode_info = check_unicode_boxes(png_path)

        # 综合评分 (各维度加权)
        # 背景色一致性纳入排版审美
        layout_score = round((dpi_info['score'] + dim_info['score'] + bg_info['score']) / 3, 1)
        dim_scores = {
            '标注完整性': round(py_info['score'], 1),
            '配色科学性': round(3.0 - (1.0 if not py_info['details'].get('colorblind_safe', True) else 0) if 'colorblind_safe' in py_info['details'] else 3.0, 1),
            '排版审美':   layout_score,
            '技术规范':   round(size_info['score'], 1),
        }
        # 配色科学性上限3, 下限0
        dim_scores['配色科学性'] = max(0, min(3, dim_scores['配色科学性']))
        # 排版审美上限2
        dim_scores['排版审美'] = max(0, min(2, dim_scores['排版审美']))
        # 技术规范上限2
        dim_scores['技术规范'] = max(0, min(2, dim_scores['技术规范']))

        overall = round(sum(dim_scores.values()), 1)
        total_score += overall

        all_issues = (dpi_info.get('issues', []) + size_info.get('issues', []) +
                      dim_info.get('issues', []) + bg_info.get('issues', []) +
                      py_info.get('issues', []) +
                      unicode_info.get('issues', []))

        grade = 'A' if overall >= 8 else ('B' if overall >= 6 else ('C' if overall >= 4 else 'D'))

        results.append({
            'file': rel_path,
            'name': name,
            'overall': overall,
            'grade': grade,
            'dimensions': dim_scores,
            'dpi': dpi_info.get('dpi_x', 0),
            'size_kb': size_info.get('size_kb', 0),
            'issues': all_issues,
            'details': py_info.get('details', {}),
        })

    avg_score = round(total_score / len(results), 1) if results else 0

    return {
        'results': results,
        'avg_score': avg_score,
        'total_figures': len(results),
        'grade_distribution': {
            'A': sum(1 for r in results if r['grade'] == 'A'),
            'B': sum(1 for r in results if r['grade'] == 'B'),
            'C': sum(1 for r in results if r['grade'] == 'C'),
            'D': sum(1 for r in results if r['grade'] == 'D'),
        },
    }


def render_markdown(report, solve_dir):
    """生成 Markdown 报告"""
    lines = []
    lines.append('# [CHART] 图表质量审查报告')
    lines.append(f'')
    lines.append(f'**审查时间**: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}')
    lines.append(f'**审查目录**: `{solve_dir}`')
    lines.append(f'**图表总数**: {report["total_figures"]}')
    lines.append(f'**平均分**: {report["avg_score"]}/10')
    lines.append(f'')
    lines.append(f'## 等级分布')
    gd = report['grade_distribution']
    lines.append(f'| 等级 | 数量 |')
    lines.append(f'|------|------|')
    for grade in ['A', 'B', 'C', 'D']:
        lines.append(f'| {grade} | {gd[grade]} |')
    lines.append(f'')

    # 判定（附门禁分级标注）
    gate_tier = "[脚本验证]"
    gate_explain = ("DPI/尺寸/文件大小: 确定性检查 | "
                    "源码分析(colormap/标注/配色): 基于正则模式匹配的启发式检查 | "
                    "Unicode方块: 像素分布分析")
    if report['avg_score'] >= 8:
        lines.append(f'[PASS] **通过** {gate_tier} — 图表质量达标, 可以进入论文写作阶段')
    elif report['avg_score'] >= 6:
        lines.append(f'[WARN] **需改进** {gate_tier} — 图表质量一般, 建议修复后再进入 Phase 3')
    else:
        lines.append(f'[FAIL] **不通过** {gate_tier} — 图表质量不足, 必须修复后重新审查')
    lines.append(f'')
    lines.append(f'> [INFO] {gate_explain}')

    lines.append(f'')
    lines.append(f'## 逐图详情')
    lines.append(f'')

    for r in report['results']:
        emoji = {'A': '[A]', 'B': '[B]', 'C': '[C]', 'D': '[D]'}.get(r['grade'], '[?]')
        lines.append(f'### {emoji} {r["name"]} — {r["overall"]}/10 ({r["grade"]})')
        lines.append(f'')
        lines.append(f'- **文件**: `{r["file"]}`')
        lines.append(f'- **DPI**: {r["dpi"]:.0f} | **大小**: {r["size_kb"]}KB')
        lines.append(f'')
        lines.append(f'| 维度 | 得分 |')
        lines.append(f'|------|------|')
        for dim, score in r['dimensions'].items():
            lines.append(f'| {dim} | {score} |')
        lines.append(f'')

        if r['issues']:
            lines.append(f'**问题清单**:')
            for issue in r['issues']:
                lines.append(f'- {issue}')
            lines.append(f'')

    # 汇总问题
    all_issues = []
    for r in report['results']:
        all_issues.extend(r['issues'])
    if all_issues:
        unique_issues = list(dict.fromkeys(all_issues))
        lines.append(f'## [FIX] 待修复问题汇总 ({len(unique_issues)} 项)')
        for i, issue in enumerate(unique_issues, 1):
            lines.append(f'{i}. {issue}')

    lines.append(f'')
    lines.append(f'---')
    lines.append(f'*报告由 check_figures.py v12.2 自动生成*')

    return '\n'.join(lines)


# ═══════════════════════════════════════════════════════════════
# 主入口
# ═══════════════════════════════════════════════════════════════

def main():
    if len(sys.argv) < 2:
        print('用法: python 审稿/check_figures.py <求解目录>')
        print('示例: python 审稿/check_figures.py E:/数学建模/测试/求解/')
        sys.exit(1)

    solve_dir = sys.argv[1]
    if not os.path.isdir(solve_dir):
        print(f'[FAIL] 目录不存在: {solve_dir}')
        sys.exit(1)

    # 收集 PNG 文件
    png_files = []
    for root, _, files in os.walk(solve_dir):
        for f in files:
            if f.lower().endswith('.png') and '图片' in root:
                png_files.append(os.path.join(root, f))

    if not png_files:
        print('[WARN] 未找到 PNG 图表文件')
        # 仍然输出空报告
        report = {'results': [], 'avg_score': 0, 'total_figures': 0, 'grade_distribution': {'A':0,'B':0,'C':0,'D':0}}
    else:
        print(f'[SCAN] 扫描到 {len(png_files)} 张图, 正在审查...')
        report = generate_report(png_files, solve_dir)

    # 输出报告
    md = render_markdown(report, solve_dir)
    report_path = os.path.join(solve_dir, '图表质量报告.md')
    with open(report_path, 'w', encoding='utf-8') as f:
        f.write(md)

    print(f'[REPORT] 报告已保存: {report_path}')
    print(f'[CHART] 平均分: {report["avg_score"]}/10 | A:{report["grade_distribution"]["A"]} B:{report["grade_distribution"]["B"]} C:{report["grade_distribution"]["C"]} D:{report["grade_distribution"]["D"]}')
    print(md[:500])

if __name__ == '__main__':
    main()
